import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Buscar_Orders_Empresa } from '../actions/empresaActions';

const CompanyOrders = ({ id }) => {
  const dispatch = useDispatch();
  const { orders, error } = useSelector(state => state.empresa);

  useEffect(() => {
    dispatch(Buscar_Orders_Empresa(id));
  }, [dispatch, id]);

  if (error) {
    return <div>Error: {error.error}</div>; // Muestra el error
  }

  if (orders.length === 0) {
    return <div>No hay órdenes para esta empresa.</div>; // Manejo cuando no hay órdenes
  }

  return (
    <div>
      {orders.map(order => (
        <div key={order.idVentas}>
          {/* Renderiza los detalles de la orden aquí */}
          <p>{JSON.stringify(order)}</p>
        </div>
      ))}
    </div>
  );
};

export default CompanyOrders;
